create or replace function public.ls_group_create(title text, peers uuid[]) returns uuid language plpgsql security definer set search_path='' as $$ declare gid uuid; p uuid; begin if auth.uid() is null or length(trim(title)) not between 1 and 80 then raise exception 'Ungültige Gruppe'; end if; if (select count(distinct x) from unnest(peers) as u(x) where x is not null and x<>auth.uid())<2 then raise exception 'Wähle mindestens zwei Freunde aus'; end if; insert into public.ls_groups(name,owner) values(trim(title),auth.uid()) returning id into gid; insert into public.ls_group_members values(gid,auth.uid()); foreach p in array peers loop if not exists(select 1 from public.ls_connections c where c.accepted and ((c.sender=auth.uid() and c.recipient=p) or(c.recipient=auth.uid() and c.sender=p))) then raise exception 'Keine Freundschaft'; end if; insert into public.ls_group_members values(gid,p) on conflict do nothing; end loop; return gid; end $$;
notify pgrst,'reload schema';
